static std::vector<uint8_t> transfer(Peripheral::Lcd& lcd,uint32_t now,unsigned count){std::vector<uint8_t> bytes;lcd.poll(now);assert(lcd.busy()&&(TWCR&_BV(TWSTA)));TWSR=0x08;TWCR=_BV(TWINT)|_BV(TWEN);lcd.poll(now);assert(TWDR==(PERIPHERAL_LCD_ADDRESS<<1));TWSR=0x18;lcd.poll(now);bytes.push_back(uint8_t(TWDR));for(unsigned i=1;i<count;i++){TWSR=0x28;lcd.poll(now);bytes.push_back(uint8_t(TWDR));}TWSR=0x28;lcd.poll(now);assert(TWCR&_BV(TWSTO));TWCR=_BV(TWEN);lcd.poll(now);assert(!lcd.busy());return bytes;}

static uint8_t decodeByte(const std::vector<uint8_t>& bytes){uint8_t value=0;const uint8_t bits[4]={PERIPHERAL_LCD_D4_BIT,PERIPHERAL_LCD_D5_BIT,PERIPHERAL_LCD_D6_BIT,PERIPHERAL_LCD_D7_BIT};for(uint8_t i=0;i<4;i++){if(bytes[0]&_BV(bits[i]))value|=uint8_t(1)<<(i+4);if(bytes[3]&_BV(bits[i]))value|=uint8_t(1)<<i;}return value;}
static void refresh(Peripheral::Lcd& lcd,char* image,uint32_t& now,uint8_t changes){for(uint8_t i=0;i<changes;i++){uint8_t address=decodeByte(transfer(lcd,now++,6))&0x7f;auto data=transfer(lcd,now++,6);assert(data[0]&_BV(PERIPHERAL_LCD_RS_BIT));uint8_t cell=address<16?address:uint8_t(address-0x40+16);assert(cell<32);image[cell]=char(decodeByte(data));}}
static void safetyDisplay(){Peripheral::Engine engine;Peripheral::Lcd lcd;Proto::Frame req,out;uint8_t p[24]={0};Proto::put32(p,1);Proto::put32(p+4,Proto::MODEL_ID);p[8]=Proto::LABELS_VERSION;Proto::make(req,Proto::HELLO,0,0,p,9);engine.handle(req,out,0);Proto::put32(p+4,1);Proto::put16(p+8,1);Proto::make(req,Proto::STOP_ALL,1,0,p,10);engine.handle(req,out,0);p[8]=2;p[9]=3;p[10]=8;Proto::put16(p+11,500);Proto::make(req,Proto::ACTUATE_BATCH,2,0,p,13);engine.handle(req,out,0);assert(engine.outputs().lights&&engine.outputs().horn);Proto::SharedState state={1,1,1,2,1,1,0,0,1,true,0};Proto::encodeState(p,state);Proto::make(req,Proto::STATE_SYNC,2,0,p,22);engine.handle(req,out,0);lcd.setup(0);transfer(lcd,40,3);transfer(lcd,45,3);transfer(lcd,46,3);transfer(lcd,47,3);transfer(lcd,48,6);transfer(lcd,49,6);transfer(lcd,50,6);transfer(lcd,52,6);uint32_t now=54;char image[32]={0};lcd.display(engine);refresh(lcd,image,now,32);assert(image[4]=='F'&&image[10]=='1'&&image[14]=='1');engine.adas(true);lcd.display(engine);refresh(lcd,image,now,4);assert(image[4]=='?'&&image[10]=='0'&&image[14]=='0'&&image[31]=='!');assert(engine.snapshot().appliedDrive==1);engine.adas(false);Proto::put32(p,1);Proto::put32(p+4,2);Proto::put16(p+8,1);Proto::make(req,Proto::STOP_ALL,3,0,p,10);engine.handle(req,out,0);p[8]=2;p[9]=3;p[10]=8;Proto::put16(p+11,500);Proto::make(req,Proto::ACTUATE_BATCH,4,0,p,13);engine.handle(req,out,0);lcd.display(engine);refresh(lcd,image,now,3);assert(image[4]=='?'&&image[10]=='1'&&image[14]=='1'&&image[31]==' ');}
